import{_ as p,a0 as r,w as u,s,I as t,x as n,a1 as i,A as l,ao as g}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const A=JSON.parse('{"title":"Linux_Logo – 輸出彩色 ANSI Linux 發行版徽標的命令列工具 | LCTT x X-CMD","titleTemplate":false,"description":"Linux_Logo – 輸出彩色 ANSI Linux 發行版徽標的命令列工具 | LCTT (201507) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux_Logo – 輸出彩色 ANSI Linux 發行版徽標的命令列工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux_Logo – 輸出彩色 ANSI Linux 發行版徽標的命令列工具 | LCTT (201507) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201507/20150612 Linux_Logo--A Command Line Tool to Print Color ANSI Logos of Linux Distributions","title":"Linux_Logo – 輸出彩色 ANSI Linux 發行版徽標的命令列工具","tag":"201507","desc":""},"relativePath":"201507/20150612 Linux_Logo--A Command Line Tool to Print Color ANSI Logos of Linux Distributions.md","filePath":"[post].md"}'),x={name:"201507/20150612 Linux_Logo--A Command Line Tool to Print Color ANSI Logos of Linux Distributions.md"};function d(L,o,m,a,c,w){const e=r("Link");return u(),s("div",null,[o[17]||(o[17]=t("h1",{id:"linux-logo-–-輸出彩色-ansi-linux-發行版徽標的命令列工具",tabindex:"-1"},[n("Linux_Logo – 輸出彩色 ANSI Linux 發行版徽標的命令列工具 "),t("a",{class:"header-anchor",href:"#linux-logo-–-輸出彩色-ansi-linux-發行版徽標的命令列工具","aria-label":"Permalink to “Linux_Logo – 輸出彩色 ANSI Linux 發行版徽標的命令列工具”"},"​")],-1)),o[18]||(o[18]=t("p",null,"linuxlogo（或叫 linux_logo）是一款在Linux命令列下用彩色 ANSI 代碼生成附帶有系統信息的發行版徽標的工具。",-1)),o[19]||(o[19]=t("p",null,[t("img",{src:"http://www.tecmint.com/wp-content/uploads/2015/06/Linux_Logo.png",alt:"Linux_Logo – 輸出彩色 ANSI Linux 發行版徽標"})],-1)),o[20]||(o[20]=t("p",null,[t("em",null,"Linux_Logo – 輸出彩色 ANSI Linux 發行版徽標")],-1)),o[21]||(o[21]=t("p",null,"這個小工具可以從 /proc 文件系統中獲取系統信息並可以顯示包括主機上安裝的發行版在內的很多發行版的徽標。",-1)),o[22]||(o[22]=t("p",null,"與徽標一同顯示的系統信息包括 ： Linux 內核版本，最近一次編譯Linux內核的時間，處理器/核心數量，速度，製造商，以及哪一代處理器。它還能顯示總共的物理內存大小。",-1)),o[23]||(o[23]=t("p",null,"無獨有偶，screenfetch是一個擁有類似功能的工具，它也能顯示發行版徽標，同時還提供更加詳細美觀的系統信息。我們之前已經介紹過這個工具，你可以參考一下鏈接：",-1)),t("ul",null,[t("li",null,[i(e,{href:"https://linux.cn/article-1947-1.html"},{default:l(()=>[...o[0]||(o[0]=[n("screenFetch: 命令列信息截圖工具",-1)])]),_:1})])]),o[24]||(o[24]=t("p",null,"linux_logo 和 Screenfetch 並完全一樣。儘管 screenfetch 的輸出較為整潔並提供更多細節， 但 linux_logo 則提供了更多的彩色 ANSI 圖標， 並且提供了格式化輸出的選項。",-1)),t("p",null,[o[2]||(o[2]=n("linux_logo 主要使用C語言編寫並將 linux 徽標呈現在 X 窗口系統中因此需要安裝圖形界面 X11 或 X 系統（LCTT 譯註：此處應是錯誤的。按説不需要任何圖形界面支持，並且譯者從其官方站 ",-1)),i(e,{href:"http://www.deater.net/weave/vmwprod/linux_logo"},{default:l(()=>[...o[1]||(o[1]=[n("http://www.deater.net/weave/vmwprod/linux_logo",-1)])]),_:1}),o[3]||(o[3]=n(" 也沒找到任何相關 X11的信息）。這個軟件使用GNU 2.0協議。",-1))]),o[25]||(o[25]=g(`<p>本文中，我們將使用以下環境測試 linux_logo 工具。</p><pre><code>操作系統 : Debian Jessie
處理器 : i3 / x86_64
</code></pre><h3 id="在-linux-中安裝-linux-logo工具" tabindex="-1">在 Linux 中安裝 Linux Logo工具 <a class="header-anchor" href="#在-linux-中安裝-linux-logo工具" aria-label="Permalink to “在 Linux 中安裝 Linux Logo工具”">​</a></h3><p><strong>1. linuxlogo軟件包 ( 5.11 穩定版) 可通過如下方式使用 apt, yum 或 dnf 在所有發行版中使用默認的軟件倉庫進行安裝</strong></p><pre><code># apt-get install linux_logo			[用於基於 Apt 的系統] （譯者注：Ubuntu中，該軟件包名為linuxlogo）
# yum install linux_logo			[用於基於 Yum 的系統]
# dnf install linux_logo			[用於基於 Dnf 的系統]
或
# dnf install linux_logo.x86_64			[用於 64 位系統]
</code></pre><p><strong>2. 裝好linuxlogo軟件包之後，你可以使用命令 <code>linuxlogo</code> 來獲取你當前使用的發行版的默認徽標..</strong></p><pre><code># linux_logo
或
# linuxlogo
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/06/Get-Default-OS-Logo.png" alt="獲取默認系統徽標"></p><p><em>獲取默認系統徽標</em></p><p><strong>3. 使用 <code>[-a]</code> 選項可以輸出沒有顏色的徽標。當在黑白終端裏使用 linux_logo 時，這個選項會很有用。</strong></p><pre><code># linux_logo -a
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/06/Black-and-White-Linux-Logo.png" alt="黑白 Linux 徽標"></p><p><em>黑白 Linux 徽標</em></p><p><strong>4. 使用 <code>[-l]</code> 選項可以僅輸出徽標而不包含系統信息。</strong></p><pre><code># linux_logo -l
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/06/Print-Distribution-Logo.png" alt="輸出發行版徽標"></p><p><em>輸出發行版徽標</em></p><p><strong>5. <code>[-u]</code> 選項可以顯示系統運行時間。</strong></p><pre><code># linux_logo -u
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/06/Print-System-Uptime.png" alt="輸出系統運行時間"></p><p><em>輸出系統運行時間</em></p><p><strong>6. 如果你對系統平均負載感興趣，可以使用 <code>[-y]</code> 選項。你可以同時使用多個選項。</strong></p><pre><code># linux_logo -y
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/06/Print-System-Load-Average.png" alt="輸出系統平均負載"></p><p><em>輸出系統平均負載</em></p><p>如需查看更多選項並獲取相關幫助，你可以使用如下命令。</p><pre><code># linux_logo -h
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/06/linuxlogo-options.png" alt="Linuxlogo 選項及幫助"></p><p><em>Linuxlogo選項及幫助</em></p><p><strong>7. 此工具內置了很多不同發行版的徽標。你可以使用 <code>[-L list]</code> 選項查看在這些徽標的列表。</strong></p><pre><code># linux_logo -L list
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/06/List-of-Linux-Logos.png" alt="Linux 徽標列表"></p><p><em>Linux 徽標列表</em></p><p>如果你想輸出這個列表中的任意徽標，可以使用 <code>-L NUM</code> 或 <code>-L NAME</code> 來顯示想要選中的圖標。</p><ul><li>-L NUM – 會輸出列表中序號為 NUM 的圖標 (不推薦).</li><li>-L NAME – 會輸出列表中名為 NAME 的圖標。</li></ul><p>例如，如果想要顯示 AIX 的徽標，你可以使用如下命令</p><pre><code># linux_logo -L 1
或
# linux_logo -L aix
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/06/Print-AIX-Logo.png" alt="輸出 AIX 圖標"></p><p><em>輸出 AIX 圖標</em></p><p><strong>注</strong>: 命令中的使用 <code>-L 1</code> 是因為 AIX 徽標在列表中的編號是1，而使用 <code>-L aix</code> 則是因為 AIX 徽標在列表中的名稱為 aix</p><p>同樣的，你還可以使用這些選項輸出任何圖標，以下是一些例子..</p><pre><code># linux_logo -L 27
# linux_logo -L 21
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/06/Various-Linux-Logos.png" alt="各種 Linux 徽標"></p><p><em>各種 Linux 徽標</em></p><p>你可以通過徽標對應的編號或名字使用任意徽標。</p><h3 id="一些使用-linux-logo-的建議和提示" tabindex="-1">一些使用 Linux_logo 的建議和提示### <a class="header-anchor" href="#一些使用-linux-logo-的建議和提示" aria-label="Permalink to “一些使用 Linux_logo 的建議和提示###”">​</a></h3><p><strong>8. 你可以在登錄界面輸出你的 Linux 發行版徽標。要輸出默認徽標，你可以在 <code> ~/.bashrc</code> 文件的最後添加以下內容。</strong></p><pre><code>if [ -f /usr/bin/linux_logo ]; then linux_logo; fi
</code></pre><p><strong>注</strong>: 如沒有<code> ~/.bashrc</code> 文件，你需要在當前用户的 home 目錄下新建一個。</p><p><strong>9. 在添加以上內容後，你只需要註銷並重新登錄即可看到你的發行版的默認徽標</strong></p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/06/Print-Logo-on-Login.png" alt="Print Logo on User Login"></p><p><em>在用户登錄時輸出徽標</em></p><p>其實你也可以在登錄後輸出任意圖標，只需加入以下內容：</p><pre><code>if [ -f /usr/bin/linux_logo ]; then linux_logo -L num; fi
</code></pre><p><strong>重要</strong>: 不要忘了將 num 替換成你想使用的圖標。</p><p><strong>10. 你也能直接指定徽標所在的位置來顯示你自己的徽標。</strong></p><pre><code># linux_logo -D /path/to/ASCII/logo
</code></pre><p><strong>11. 在遠程登錄時輸出圖標。</strong></p><pre><code># /usr/local/bin/linux_logo &gt; /etc/issue.net
</code></pre><p>如果你想使用　ASCII　徽標而不是含有顏色的 ANSI 徽標，則使用如下命令</p><pre><code># /usr/local/bin/linux_logo -a &gt; /etc/issue.net
</code></pre><p><strong>12. 創建一個 Linux 上的端口 - 用於回應連接的端口。要創建 Linux 端口， 則需在 /etc/services 文件中加入以下內容</strong></p><pre><code>penguin	4444/tcp	penguin
</code></pre><p>這裏的 <code>4444</code> 是一個未被任何其他資源使用的空閒端口。你也可以使用其他端口。你還需要在 /etc/inetd.conf中加入以下內容：</p><pre><code>penguin	stream	     tcp	nowait	root /usr/local/bin/linux_logo 
</code></pre><p>並使用以下命令重啓 inetd 服務</p><pre><code># killall -HUP inetd
</code></pre><p>（LCTT 譯註：然後你就可以遠程或本地連接到這個端口，並顯示這個徽標了。）</p><p>linux_logo 還可以用做啓動腳本來愚弄攻擊者或對你朋友使用惡作劇。這是一個我經常在我的腳本中用來獲取不同發行版輸出的好工具。</p><p>試過一次後，你就不會忘記的。讓我們知道你對這個工具的想法及它對你的作用吧。 不要忘記給評論、點贊或分享！</p><hr>`,71)),t("p",null,[o[5]||(o[5]=n("via: ",-1)),i(e,{href:"http://www.tecmint.com/linux_logo-tool-to-print-color-ansi-logos-of-linux/"},{default:l(()=>[...o[4]||(o[4]=[n("http://www.tecmint.com/linux_logo-tool-to-print-color-ansi-logos-of-linux/",-1)])]),_:1})]),t("p",null,[o[9]||(o[9]=n("作者：",-1)),i(e,{href:"http://www.tecmint.com/author/avishek/"},{default:l(()=>[...o[6]||(o[6]=[n("Avishek Kumar",-1)])]),_:1}),o[10]||(o[10]=n(" 譯者：",-1)),i(e,{href:"https://github.com/KevinSJ"},{default:l(()=>[...o[7]||(o[7]=[n("KevinSJ",-1)])]),_:1}),o[11]||(o[11]=n(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:l(()=>[...o[8]||(o[8]=[n("wxy",-1)])]),_:1})]),t("p",null,[o[14]||(o[14]=n("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...o[12]||(o[12]=[n("LCTT",-1)])]),_:1}),o[15]||(o[15]=n(" 原創翻譯，",-1)),i(e,{href:"https://linux.cn/"},{default:l(()=>[...o[13]||(o[13]=[n("Linux中國",-1)])]),_:1}),o[16]||(o[16]=n(" 榮譽推出",-1))])])}const T=p(x,[["render",d]]);export{A as __pageData,T as default};
